    return _TABLE_MAP.get(table, table)


# Columns that are stored as SQLite INTEGER but represent booleans.
_BOOLEAN_COLUMNS = {"is_self", "cellular", "wifi", "location_service", "low_battery_mode"}
# Columns to expose as floats.
